        setTestEnvValue("OPENCLAW_GATEWAY_TOKEN", token);
        const cfg: OpenClawConfig = {
          agents: {
            defaults: { workspace: home.workspaceDir, skipBootstrap: true },
            entries: { main: {} },
          },
          gateway: { mode: "local", auth: { mode: "token", token }, controlUi: { enabled: false } },
          tools: { sessions: { visibility: "all" } },
          plugins: { slots: { memory: "none" } },
          skills: { load: { watch: false } },
          hooks: { enabled: false },
        };
        gateway = await startGatewayWithClient({
          cfg,
          configPath: await createGatewayConfigPath(home.tempHome),
          token,
          scopes: ["operator.admin", "operator.read", "operator.write"],
          clientDisplayName: "inventory-error-runtime-proof",
        });
        await gateway.server.startupSettled;
        console.log(
          "INVENTORY_GATEWAY_PROOF_STEP " +
            JSON.stringify({ stage: "authenticated-gateway-ready" }),
